arguments.keystrokes:
cat > /etc/nginx/nginx.conf << 'NGINXCONF'
user www-data;
worker_processes auto;
pid /run/nginx.pid;
include /etc/nginx/modules-enabled/*.conf;

events {
    worker_connections 768;
}

http {
    sendfile on;
    tcp_nopush on;
    types_hash_max_size 2048;
    include /etc/nginx/mime.types;
    default_type application/octet-stream;

    # Custom log format
    log_format benchmark '$time_local $request_method $status "$http_user_agent"';

    # Rate limiting zone
    limit_req_zone $binary_remote_addr zone=req_limit:10m rate=10r/s;

    # SSL settings (if needed)
    ssl_protocols TLSv1 TLSv1.1 TLSv1.2 TLSv1.3;
    ssl_prefer_server_ciphers on;

    # Logging
    access_log /var/log/nginx/access.log;
    error_log /var/log/nginx/error.log;

    # Gzip
    gzip on;

    include /etc/nginx/conf.d/*.conf;
    include /etc/nginx/sites-enabled/*;
}
NGINXCONF

cat > /etc/nginx/conf.d/benchmark-site.conf << 'SITECONF'
server {
    listen 8080;
    server_name localhost;

    root /var/www/html;
    index index.html;

    # Custom logging
    access_log /var/log/nginx/benchmark-access.log benchmark;
    error_log /var/log/nginx/benchmark-error.log;

    # Rate limiting
    limit_req zone=req_limit burst=10 nodelay;

    # Custom 404 error page
    error_page 404 /404.html;
    location = /404.html {
        internal;
    }

    location / {
        try_files $uri $uri/ =404;
    }
}
SITECONF

